purchase-products-help.stdout:
{
  "ok": true,
  "data": {
    "usage": "Usage:\n  outrank-cli billing purchase-products quote --additional-products <n> [--idempotency-key <key>]\n  outrank-cli billing purchase-products buy --additional-products <n> --confirm-charge-cents <n> --idempotency-key <key>"
  },
  "agent_guidance": "Use `quote` first, then `buy` with the quoted recurring total and a stable idempotency key."
}

portal-url-no-key.stdout:
{
  "ok": false,
  "error": {
    "code": "CLI_AUTH_REQUIRED",
    "message": "No Outrank API key is configured."
  },
  "agent_guidance": "Run `outrank-cli auth login <api-key>` to store a key locally, or set OUTRANK_API_KEY in the environment before retrying."
}

portal-url-non-json.stdout:
{
  "ok": false,
  "error": {
    "code": "CLI_NON_JSON_RESPONSE",
    "message": "Outrank returned HTTP 502 without a JSON body.",
    "details": {
      "status": 502,
      "url": "https://www.outrank.so/api/agent/v1/billing/portal-url"
    }
  },
  "agent_guidance": "The CLI expects the agent API to return JSON. Check the base URL and server deployment."
}

portal-url-network-error.stdout:
{
  "ok": false,
  "error": {
    "code": "CLI_NETWORK_ERROR",
    "message": "Request failed: fetch failed"
  },
  "agent_guidance": "The CLI could not reach https://www.outrank.so. Confirm OUTRANK_BASE_URL, the user's network, and the Outrank deployment, then retry."
}

